const input = $input.first().json;

const telefono = input.body?.whatsappInboundMessage?.from;
const mensaje = input.body?.whatsappInboundMessage?.text?.body || '';
const messageId = input.body?.whatsappInboundMessage?.id;

if (!telefono) {
  throw new Error('No se pudo extraer el telefono del remitente.');
}

return [{ json: { telefono, mensaje, messageId } }];

const input = $input.first().json;
const key = input.telefono;
const data = $getWorkflowStaticData('global');
data.turnos = data.turnos || {};

data.turnos[key] = (data.turnos[key] || 0) + 1;
const turno = data.turnos[key];
const espera = turno === 1 ? (3 + Math.random()) : 2;

return [{ json: { ...input, espera_segundos: espera } }];
